import { useMutation, useQuery, useQueryClient, type QueryClient } from "@tanstack/react-query";
import type {
  AgentTicketUpdateInput,
  BoardSnapshot,
  CancelRunInput,
  ClarificationAnswerInput,
  CodexStatus,
  CreateDraftInput,
  EpicSubticketCreateInput,
  EpicSubticketLinkInput,
  EpicSubticketUnlinkInput,
  FeatureSubticketLinkInput,
  FeatureTaskCreateRequest,
  GitMetadata,
  GitMetadataOptions,
  ProjectOpenInEditorInput,
  RendererRunEvent,
  RepositoryChatInput,
  RunSummary,
  StartRunInput,
  TicketAttachmentSaveInput,
  TicketMoveInput,
  TicketRedraftInput,
  TicketRecord,
  TicketSaveInput
} from "@shared/schemas";
import { relayApi } from "./relayApi";

type ProjectPath = string | null | undefined;
type TicketId = string | null | undefined;
type RunId = string | null | undefined;

export const relayQueryKeys = {
  projects: ["relay", "projects"] as const,
  board: (projectPath: ProjectPath) => ["relay", "board", projectPath ?? null] as const,
  ticket: (projectPath: ProjectPath, ticketId: TicketId) => ["relay", "ticket", projectPath ?? null, ticketId ?? null] as const,
  ticketClarifications: (projectPath: ProjectPath, ticketId: TicketId) =>
    ["relay", "ticket", projectPath ?? null, ticketId ?? null, "clarifications"] as const,
  ticketReferences: (projectPath: ProjectPath) => ["relay", "ticket-references", projectPath ?? null] as const,
  codexStatus: ["relay", "codex", "status"] as const,
  gitMetadata: (projectPath: ProjectPath) => ["relay", "git-metadata", projectPath ?? null] as const,
  runEvents: (projectPath: ProjectPath, ticketId: TicketId, runId: RunId) =>
    ["relay", "run-events", projectPath ?? null, ticketId ?? null, runId ?? null] as const,
  runSummary: (projectPath: ProjectPath, ticketId: TicketId) => ["relay", "run-summary", projectPath ?? null, ticketId ?? null] as const
};

export const relayErrorMessage = (error: unknown, fallback: string): string => (error instanceof Error ? error.message : fallback);

const invalidateProjectData = async (queryClient: QueryClient, projectPath?: string | null): Promise<void> => {
  await Promise.all([
    queryClient.invalidateQueries({ queryKey: relayQueryKeys.projects }),
    projectPath ? queryClient.invalidateQueries({ queryKey: relayQueryKeys.board(projectPath) }) : Promise.resolve(),
    projectPath ? queryClient.invalidateQueries({ queryKey: relayQueryKeys.ticketReferences(projectPath) }) : Promise.resolve(),
    projectPath ? queryClient.invalidateQueries({ queryKey: relayQueryKeys.gitMetadata(projectPath) }) : Promise.resolve()
  ]);
};

const invalidateTicketData = async (queryClient: QueryClient, projectPath: string, ticketId?: string | null): Promise<void> => {
  await Promise.all([
    invalidateProjectData(queryClient, projectPath),
    ticketId ? queryClient.invalidateQueries({ queryKey: relayQueryKeys.ticket(projectPath, ticketId) }) : Promise.resolve(),
    ticketId ? queryClient.invalidateQueries({ queryKey: relayQueryKeys.ticketClarifications(projectPath, ticketId) }) : Promise.resolve(),
    ticketId ? queryClient.invalidateQueries({ queryKey: relayQueryKeys.runSummary(projectPath, ticketId) }) : Promise.resolve(),
    ticketId ? queryClient.invalidateQueries({ queryKey: ["relay", "run-events", projectPath, ticketId] }) : Promise.resolve()
  ]);
};

export const invalidateRelayProjectData = invalidateProjectData;
export const invalidateRelayTicketData = invalidateTicketData;

export const useProjectsQuery = () =>
  useQuery({
    queryKey: relayQueryKeys.projects,
    queryFn: () => relayApi.projects.list()
  });

export const useBoardQuery = (projectPath: ProjectPath) =>
  useQuery({
    queryKey: relayQueryKeys.board(projectPath),
    queryFn: () => relayApi.board.read({ projectPath: projectPath as string }),
    enabled: Boolean(projectPath)
  });

export const useTicketQuery = (projectPath: ProjectPath, ticketId: TicketId) =>
  useQuery({
    queryKey: relayQueryKeys.ticket(projectPath, ticketId),
    queryFn: () => relayApi.tickets.read({ projectPath: projectPath as string, ticketId: ticketId as string }),
    enabled: Boolean(projectPath && ticketId)
  });

export const useTicketClarificationsQuery = (projectPath: ProjectPath, ticketId: TicketId) =>
  useQuery({
    queryKey: relayQueryKeys.ticketClarifications(projectPath, ticketId),
    queryFn: () => relayApi.tickets.clarifications({ projectPath: projectPath as string, ticketId: ticketId as string }),
    enabled: Boolean(projectPath && ticketId)
  });

export const useTicketReferencesQuery = (projectPath: ProjectPath) =>
  useQuery({
    queryKey: relayQueryKeys.ticketReferences(projectPath),
    queryFn: () => relayApi.tickets.references({ projectPath: projectPath as string }),
    enabled: Boolean(projectPath)
  });

export const useCodexStatusQuery = () =>
  useQuery({
    queryKey: relayQueryKeys.codexStatus,
    queryFn: () => relayApi.codex.status(),
    staleTime: 30_000,
    refetchOnWindowFocus: true,
    retry: 2,
    retryDelay: (attempt) => Math.min(1_000 * 2 ** attempt, 4_000)
  });

export const useProjectGitMetadataQuery = (projectPath: ProjectPath, options?: GitMetadataOptions) =>
  useQuery({
    queryKey: relayQueryKeys.gitMetadata(projectPath),
    queryFn: () => relayApi.projects.gitMetadata({ projectPath: projectPath as string, options }),
    enabled: Boolean(projectPath),
    retry: false
  });

export const useRunEventsQuery = (projectPath: ProjectPath, ticketId: TicketId, runId: RunId) =>
  useQuery({
    queryKey: relayQueryKeys.runEvents(projectPath, ticketId, runId),
    queryFn: () =>
      relayApi.codex.readRunEvents({
        projectPath: projectPath as string,
        ticketId: ticketId as string,
        runId: runId as string
      }),
    enabled: Boolean(projectPath && ticketId && runId)
  });

export const useRunSummaryQuery = (projectPath: ProjectPath, ticketId: TicketId) =>
  useQuery({
    queryKey: relayQueryKeys.runSummary(projectPath, ticketId),
    queryFn: () => relayApi.codex.readLatestRunSummary({ projectPath: projectPath as string, ticketId: ticketId as string }),
    enabled: Boolean(projectPath && ticketId)
  });

export const useAddProjectMutation = () => {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: () => relayApi.projects.addFolder(),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: relayQueryKeys.projects });
    }
  });
};

export const useRemoveProjectMutation = () => {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (projectPath: string) => relayApi.projects.removeFromSidebar({ projectPath }),
    onSuccess: async (_projects, projectPath) => {
      await invalidateProjectData(queryClient, projectPath);
    }
  });
};

export const useRevealProjectMutation = () => useMutation({ mutationFn: (projectPath: string) => relayApi.projects.revealInFinder({ projectPath }) });

export const relayOpenProjectInEditor = (input: ProjectOpenInEditorInput) => relayApi.projects.openInEditor(input);

export const useOpenProjectInEditorMutation = () =>
  useMutation({ mutationFn: relayOpenProjectInEditor });

export const useRefreshCodexStatusMutation = () => {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: () => relayApi.codex.status(),
    onSuccess: (status) => {
      queryClient.setQueryData(relayQueryKeys.codexStatus, status);
    },
    onSettled: async () => {
      await queryClient.invalidateQueries({ queryKey: relayQueryKeys.codexStatus });
    }
  });
};

export const useMoveTicketMutation = () => {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (input: TicketMoveInput) => relayApi.tickets.move(input),
    onSuccess: async (board, input) => {
      queryClient.setQueryData(relayQueryKeys.board(input.projectPath), board);
      await invalidateTicketData(queryClient, input.projectPath, input.ticketId);
    }
  });
};

export const useCreateDraftMutation = () => {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (input: CreateDraftInput) => relayApi.tickets.createDraft(input),
    onSuccess: async (_result, input) => {
      await invalidateProjectData(queryClient, input.projectPath);
    }
  });
};

export const useRedraftTicketMutation = () => {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (input: TicketRedraftInput) => relayApi.tickets.redraft(input),
    onSuccess: async (_result, input) => {
      await invalidateTicketData(queryClient, input.projectPath, input.ticketId);
    }
  });
};

export const useSaveTicketMutation = () => {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (input: TicketSaveInput) => relayApi.tickets.save(input),
    onSuccess: async (ticket, input) => {
      queryClient.setQueryData(relayQueryKeys.ticket(input.projectPath, ticket.frontMatter.id), ticket);
      await invalidateTicketData(queryClient, input.projectPath, ticket.frontMatter.id);
    }
  });
};

export const useSaveTicketAttachmentMutation = () =>
  useMutation({ mutationFn: (input: TicketAttachmentSaveInput) => relayApi.tickets.saveAttachment(input) });

export const useStartTicketUpdateMutation = () =>
  useMutation({ mutationFn: (input: AgentTicketUpdateInput) => relayApi.tickets.startAgentUpdate(input) });

export const useCancelTicketUpdateMutation = () =>
  useMutation({ mutationFn: (runId: string) => relayApi.tickets.cancelAgentUpdate({ runId }) });

export const usePreflightRunMutation = () => useMutation({ mutationFn: (input: StartRunInput) => relayApi.codex.preflightRun(input) });

export const useStartRunMutation = () => {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ resume, input }: { resume: boolean; input: StartRunInput }) =>
      resume ? relayApi.codex.resumeRun(input) : relayApi.codex.startRun(input),
    onSuccess: async (_result, { input }) => {
      await invalidateTicketData(queryClient, input.projectPath, input.ticketId);
    }
  });
};

export const useCancelRunMutation = () => {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (input: CancelRunInput) => relayApi.codex.cancelRun(input),
    onSuccess: async (_result, input) => {
      await Promise.all([
        invalidateTicketData(queryClient, input.projectPath, input.ticketId),
        queryClient.invalidateQueries({ queryKey: relayQueryKeys.gitMetadata(input.projectPath) })
      ]);
    }
  });
};

export const useAnswerClarificationMutation = () => {
  const queryClient = useQueryClient();

:root {
  color-scheme: dark;
  --relay-font-sans:
    Inter, "DM Sans", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --relay-font-mono: "SF Mono", "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;
  --relay-bg: #0f1012;
  --relay-chrome: #111217;
  --relay-sidebar: #121419;
  --relay-surface: #15171c;
  --relay-surface-2: #191c22;
  --relay-surface-3: #1f232a;
  --relay-surface-hover: #242933;
  --relay-surface-active: #2a303a;
  --relay-popover: #171a20;
  --relay-input: #12151a;
  --relay-text: rgb(255 255 255 / 92%);
  --relay-text-muted: rgb(255 255 255 / 58%);
  --relay-text-subtle: rgb(255 255 255 / 38%);
  --relay-text-inverse: #ffffff;
  --relay-border-soft: rgb(255 255 255 / 4%);
  --relay-border: rgb(255 255 255 / 7%);
  --relay-border-strong: rgb(255 255 255 / 12%);
  --relay-primary: #a94d47;
  --relay-primary-hover: #bc625b;
  --relay-primary-active: #8f403b;
  --relay-primary-muted: rgb(188 98 91 / 13%);
  --relay-primary-text: #e08b82;
  --relay-ring: #d2746d;
  --relay-info: #8fb8ff;
  --relay-info-muted: rgb(143 184 255 / 14%);
  --relay-success: #87d38b;
  --relay-success-muted: rgb(135 211 139 / 13%);
  --relay-warning: #e7c36a;
  --relay-warning-muted: rgb(231 195 106 / 14%);
  --relay-danger: #ff8f80;
  --relay-danger-muted: rgb(255 143 128 / 14%);
  --relay-info-text: #b5ccff;
  --relay-success-text: #a7dfa9;
  --relay-warning-text: #f3d78c;
  --relay-danger-text: #ffb1a7;
  --relay-radius-xs: 4px;
  --relay-radius-sm: 6px;
  --relay-radius-md: 8px;
  --relay-radius-lg: 8px;
  --relay-space-1: 4px;
  --relay-space-2: 8px;
  --relay-space-3: 12px;
  --relay-space-4: 16px;
  --relay-space-5: 20px;
  --relay-space-6: 24px;
  --relay-text-xs: 11px;
  --relay-text-sm: 12px;
  --relay-text-md: 13px;
  --relay-text-base: 14px;
  --relay-text-lg: 16px;
  --relay-text-xl: 20px;
  --relay-shadow-sm: 0 8px 24px rgb(0 0 0 / 20%);
  --relay-shadow-card: 0 14px 36px rgb(0 0 0 / 23%);
  --relay-shadow-panel: 0 22px 70px rgb(0 0 0 / 32%);
  --relay-shadow-modal: 0 34px 120px rgb(0 0 0 / 54%);
  --relay-inset-highlight: inset 0 1px 0 rgb(255 255 255 / 5%);
  --relay-focus-ring: 0 0 0 1px color-mix(in srgb, var(--relay-ring) 72%, transparent), 0 0 0 5px rgb(210 116 109 / 12%);
  --relay-ease: cubic-bezier(0.2, 0.8, 0.2, 1);
  --relay-spring: cubic-bezier(0.16, 1, 0.3, 1);
  font-family: var(--relay-font-sans);
  background: var(--relay-bg);
  color: var(--relay-text);
  font-synthesis: none;
  text-rendering: optimizeLegibility;
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  width: 100%;
  height: 100%;
}

body {
  margin: 0;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  background:
    linear-gradient(145deg, rgb(255 255 255 / 3%) 0%, transparent 34%),
    linear-gradient(180deg, var(--relay-chrome) 0%, var(--relay-bg) 54%);
  color: var(--relay-text);
  font-size: var(--relay-text-base);
  line-height: 1.5;
}

button,
input,
textarea,
select {
  font: inherit;
}

button {
  min-height: 32px;
  border: 1px solid transparent;
  border-radius: var(--relay-radius-md);
  background: rgb(255 255 255 / 5%);
  color: var(--relay-text);
  padding: 0 11px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--relay-space-2);
  cursor: pointer;
  box-shadow:
    var(--relay-inset-highlight),
    0 8px 18px rgb(0 0 0 / 8%);
  transition:
    background-color 160ms var(--relay-ease),
    border-color 160ms var(--relay-ease),
    color 160ms var(--relay-ease),
    opacity 160ms var(--relay-ease),
    box-shadow 180ms var(--relay-ease),
    transform 180ms var(--relay-spring);
}

button:hover {
  background: rgb(255 255 255 / 8%);
  box-shadow:
    var(--relay-inset-highlight),
    0 10px 26px rgb(0 0 0 / 16%);
  transform: translateY(-1px);
}

button:active {
  transform: translateY(0);
  background: var(--relay-surface-active);
  box-shadow: var(--relay-inset-highlight);
}

button:focus-visible,
input:focus-visible,
textarea:focus-visible,
select:focus-visible {
  outline: none;
  box-shadow: var(--relay-focus-ring);
}

button:disabled {
  cursor: not-allowed;
  opacity: 0.52;
  transform: none;
}

button svg {
  flex: 0 0 auto;
  opacity: 0.86;
}

input,
textarea,
select {
  width: 100%;
  border: 1px solid transparent;
  border-radius: var(--relay-radius-md);
  background: var(--relay-input);
  color: var(--relay-text);
  padding: 8px 10px;
  outline: none;
  box-shadow:
    var(--relay-inset-highlight),
    inset 0 0 0 1px rgb(255 255 255 / 4%);
  transition:
    background-color 160ms var(--relay-ease),
    border-color 160ms var(--relay-ease),
    box-shadow 180ms var(--relay-ease);
}

input::placeholder,
textarea::placeholder {
  color: var(--relay-text-subtle);
}

input:hover,
textarea:hover,
select:hover {
  box-shadow:
    var(--relay-inset-highlight),
    inset 0 0 0 1px rgb(255 255 255 / 8%);
}

textarea {
  min-height: 132px;
  resize: vertical;
  line-height: 1.45;
}

select {
  color: var(--relay-text);
}

option {
  background: var(--relay-popover);
  color: var(--relay-text);
}

pre,
code {
  font-family: var(--relay-font-mono);
}

kbd {
  min-height: 18px;
  border: 0;
  border-radius: var(--relay-radius-xs);
  background: rgb(255 255 255 / 13%);
  color: currentColor;
  padding: 1px 5px;
  font-family: var(--relay-font-mono);
  font-size: var(--relay-text-xs);
  font-weight: 650;
  line-height: 1.25;
  white-space: nowrap;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  clip-path: inset(50%);
  white-space: nowrap;
}

::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: transparent;
}

::-webkit-scrollbar-thumb {
  border: 2px solid transparent;
  border-radius: 999px;
  background: rgb(255 255 255 / 18%);
  background-clip: padding-box;
}

::-webkit-scrollbar-thumb:hover {
  background: rgb(255 255 255 / 28%);
  background-clip: padding-box;
}

.app-shell {
  display: grid;
  grid-template-columns: 282px minmax(0, 1fr);
  height: 100dvh;

import {
  boardEndpoints,
  codexEndpoints,
  decodeHttpPayload,
  projectEndpoints,
  ticketEndpoints,
  type AnyHttpEndpoint,
  type HttpEndpoint,
  type HttpEndpointRequest,
  type HttpEndpointResponse
} from "@shared/http";
import { rendererRunEventSchema } from "@shared/schemas";
import type {
  AddProjectResult,
  AgentTicketUpdateInput,
  AgentTicketUpdateStartResult,
  BoardSnapshot,
  CancelRunInput,
  ClarificationAnswerInput,
  ClarificationQuestion,
  CodexCancelRunResult,
  CodexRunPreflightResult,
  CodexRunStartResult,
  CodexStatus,
  CreateDraftInput,
  DraftIntakeInput,
  DraftIntakeResult,
  EpicSubticketCreateInput,
  EpicSubticketLinkInput,
  FeatureSubticketCreateInput,
  FeatureSubticketLinkInput,
  FeatureTaskCreateRequest,
  GitMetadata,
  GitMetadataOptions,
  ProjectOpenInEditorInput,
  ProjectOpenInEditorResult,
  ProjectSummary,
  RendererRunEvent,
  RepositoryChatInput,
  RepositoryChatResponse,
  RunSummary,
  StartRunInput,
  TicketAttachmentSaveInput,
  TicketAttachmentSaveResult,
  TicketCreateInput,
  TicketDraftStartResult,
  TicketMoveInput,
  TicketRecord,
  TicketRedraftInput,
  TicketReferenceCandidate,
  TicketSaveInput
} from "@shared/schemas";

type RelayApiConfig = {
  readonly baseUrl: string;
  readonly token: string;
};

export class RelayApiError extends Error {
  readonly code: string;
  readonly status: number;

  constructor(status: number, code: string, message: string) {
    super(message);
    this.name = "RelayApiError";
    this.status = status;
    this.code = code;
  }
}

export type RelayApiClient = {
  readonly projects: {
    readonly list: () => Promise<ProjectSummary[]>;
    readonly addFolder: () => Promise<AddProjectResult | null>;
    readonly addPath: (input: { readonly projectPath: string; readonly initializeIfMissing?: boolean }) => Promise<AddProjectResult>;
    readonly removeFromSidebar: (input: { readonly projectPath: string }) => Promise<ProjectSummary[]>;
    readonly read: (input: { readonly projectPath: string }) => Promise<ProjectSummary>;
    readonly gitMetadata: (input: { readonly projectPath: string; readonly options?: GitMetadataOptions }) => Promise<GitMetadata>;
    readonly revealInFinder: (input: { readonly projectPath: string }) => Promise<void>;
    readonly openInEditor: (input: ProjectOpenInEditorInput) => Promise<ProjectOpenInEditorResult>;
  };
  readonly board: {
    readonly read: (input: { readonly projectPath: string }) => Promise<BoardSnapshot>;
  };
  readonly tickets: {
    readonly intakeDraft: (input: DraftIntakeInput) => Promise<DraftIntakeResult>;
    readonly createDraft: (input: CreateDraftInput) => Promise<TicketDraftStartResult>;
    readonly redraft: (input: TicketRedraftInput) => Promise<TicketDraftStartResult>;
    readonly createManual: (input: { readonly projectPath: string; readonly input: TicketCreateInput }) => Promise<TicketRecord>;
    readonly createSubticket: (input: EpicSubticketCreateInput) => Promise<TicketRecord>;
    readonly linkSubticket: (input: EpicSubticketLinkInput) => Promise<BoardSnapshot>;
    readonly unlinkSubticket: (input: EpicSubticketLinkInput) => Promise<BoardSnapshot>;
    readonly createTaskUnderFeature: (input: FeatureTaskCreateRequest) => Promise<TicketRecord>;
    readonly createFeatureSubticket: (input: FeatureSubticketCreateInput) => Promise<TicketRecord>;
    readonly linkFeatureSubticket: (input: FeatureSubticketLinkInput) => Promise<BoardSnapshot>;
    readonly unlinkFeatureSubticket: (input: FeatureSubticketLinkInput) => Promise<BoardSnapshot>;
    readonly startAgentUpdate: (input: AgentTicketUpdateInput) => Promise<AgentTicketUpdateStartResult>;
    readonly cancelAgentUpdate: (input: { readonly runId: string }) => Promise<void>;
    readonly references: (input: { readonly projectPath: string }) => Promise<TicketReferenceCandidate[]>;
    readonly read: (input: { readonly projectPath: string; readonly ticketId: string }) => Promise<TicketRecord>;
    readonly save: (input: TicketSaveInput) => Promise<TicketRecord>;
    readonly saveAttachment: (input: TicketAttachmentSaveInput) => Promise<TicketAttachmentSaveResult>;
    readonly move: (input: TicketMoveInput) => Promise<BoardSnapshot>;
    readonly clarifications: (input: { readonly projectPath: string; readonly ticketId: string }) => Promise<ClarificationQuestion[]>;
    readonly answerClarification: (input: ClarificationAnswerInput) => Promise<ClarificationQuestion>;
    readonly approveScopeClarification: (input: { readonly projectPath: string; readonly ticketId: string; readonly clarificationQuestionId: string }) => Promise<AgentTicketUpdateStartResult>;
    readonly delete: (input: { readonly projectPath: string; readonly ticketId: string }) => Promise<BoardSnapshot>;
    readonly duplicate: (input: { readonly projectPath: string; readonly ticketId: string }) => Promise<TicketRecord>;
    readonly revealFile: (input: { readonly projectPath: string; readonly ticketId: string }) => Promise<void>;
  };
  readonly codex: {
    readonly status: () => Promise<CodexStatus>;
    readonly preflightRun: (input: StartRunInput) => Promise<CodexRunPreflightResult>;
    readonly startRun: (input: StartRunInput) => Promise<CodexRunStartResult>;
    readonly resumeRun: (input: StartRunInput) => Promise<CodexRunStartResult>;
    readonly cancelRun: (input: CancelRunInput) => Promise<CodexCancelRunResult>;
    readonly approveAction: (input: { readonly approvalId: string; readonly decision: "accept" | "acceptForSession" | "decline" | "cancel" }) => Promise<void>;
    readonly sendRepositoryChatMessage: (input: RepositoryChatInput) => Promise<RepositoryChatResponse>;
    readonly readRunEvents: (input: { readonly projectPath: string; readonly ticketId: string; readonly runId: string }) => Promise<RendererRunEvent[]>;
    readonly readLatestRunSummary: (input: { readonly projectPath: string; readonly ticketId: string }) => Promise<RunSummary | null>;
  };
  readonly subscribeRunEvents: (listener: (event: RendererRunEvent) => void) => () => void;
};

let testClient: RelayApiClient | null = null;
let browserClient: RelayApiClient | null = null;

const normalizeBaseUrl = (value: string): string => value.endsWith("/") ? value : `${value}/`;

const apiConfigFromLocation = (): RelayApiConfig => {
  const params = typeof window === "undefined" ? new URLSearchParams() : new URLSearchParams(window.location.search);
  return {
    baseUrl: params.get("relayApiBaseUrl") ?? "http://127.0.0.1:17654",
    token: params.get("relayApiToken") ?? "relay-dev"
  };
};

const appendQuery = (url: URL, input: Record<string, unknown>): void => {
  for (const [key, value] of Object.entries(input)) {
    if (value === undefined || value === null) continue;
    url.searchParams.set(key, String(value));
  }
};

const readError = async (response: Response): Promise<RelayApiError> => {
  try {
    const body = await response.json() as { readonly error?: { readonly code?: unknown; readonly message?: unknown } };
    const code = typeof body.error?.code === "string" ? body.error.code : "api_error";
    const message = typeof body.error?.message === "string" ? body.error.message : `Relay API request failed with HTTP ${response.status}.`;
    return new RelayApiError(response.status, code, message);
  } catch {
    return new RelayApiError(response.status, "api_error", `Relay API request failed with HTTP ${response.status}.`);
  }
};

const request = async <Endpoint extends AnyHttpEndpoint>(
  config: RelayApiConfig,
  endpoint: Endpoint,
  input: HttpEndpointRequest<Endpoint>
): Promise<HttpEndpointResponse<Endpoint>> => {
  const url = new URL(endpoint.path, normalizeBaseUrl(config.baseUrl));
  const init: RequestInit = {
    method: endpoint.method,
    headers: {
      Authorization: `Bearer ${config.token}`
    }
  };

  if (endpoint.request?.location === "query") {
    appendQuery(url, input as Record<string, unknown>);
  } else if (endpoint.request?.location === "body") {
    init.headers = {
      ...init.headers,
      "Content-Type": "application/json"
    };
    init.body = JSON.stringify(input);
  }

  const response = await fetch(url, init);
  if (!response.ok) throw await readError(response);
  if (!endpoint.response || response.status === 204) return undefined as HttpEndpointResponse<Endpoint>;
  return decodeHttpPayload(endpoint.response, await response.json()) as HttpEndpointResponse<Endpoint>;
};

const call = <Endpoint extends HttpEndpoint<unknown, unknown>>(
  config: RelayApiConfig,
  endpoint: Endpoint,
  input: HttpEndpointRequest<Endpoint>
): Promise<HttpEndpointResponse<Endpoint>> => request(config, endpoint, input);

